"% Define the open-loop transfer function L(s) = num/den
num = [1.8];
den = [1.0, 3.0, 2.0, 0.0];
L = tf(num, den);

% Compute classical stability margins
% Gm  -> gain margin (linear, absolute)
% Pm  -> phase margin (degrees)
% Wgm -> frequency at which phase crosses -180 deg (w_pc)
% Wpm -> frequency at which gain crosses 0 dB (w_gc)
[Gm, Pm, Wgm, Wpm] = margin(L);

% Convert gain margin to dB
gm_db = 20*log10(Gm);

% Map to the required output keys
w_pc = Wgm;
w_gc = Wpm;

% Build the results struct
result = struct( ...
    'gm_db', gm_db, ...
    'pm_deg', Pm, ...
    'w_gc',   w_gc, ...
    'w_pc',   w_pc );

% Serialize and write result.json to the current working directory
json_text = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_text);
fclose(fid);"
